section:
/page/1/` for every paginated section, but that URL is not
    a page: it is a ~360-byte JS/meta-refresh stub that redirects to the section
    root. Submitting content-free redirects to search engines is pointless, so they
    are filtered out here. `page/2/` and beyond are real listing pages and stay. -#}

    {%- for sitemap_entry in entries %}
    {%- if sitemap_entry.permalink is not matching(pat="/page/1/$") %}

        {{ sitemap_entry.permalink | escape_xml | safe }}
        {%- if sitemap_entry.updated %}
        {{ sitemap_entry.updated }}
        {%- endif %}

    {%- endif %}
    {%- endfor %}
